function showDialog(html, handler){$('#dialogBody').innerHTML=html;$('#dialogForm').oninput=e=>{if(e.target.matches('input, textarea, select')){const preview=$('#draftPreview');if(preview)preview.textContent='Đã sửa biểu mẫu; hãy thử lại để cập nhật kết quả.'}};const d=$('#dialog');const cancel=$('#dialogBody').querySelector('button[value=cancel]');if(cancel)cancel.formNoValidate=true;d.showModal();let busy=false;d.oncancel=e=>{if(busy)e.preventDefault()};$('#dialogForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const submit=e.submitter;if(submit?.value==='cancel'){d.close();return}busy=true;if(submit)submit.disabled=true;try{const data=new FormData(e.currentTarget);await MutationLock.run(()=>handler(data,d)); }catch(err){notify('Không thể thực hiện: '+err.message)}finally{busy=false;if(submit)submit.disabled=false}};}
