function validTabs(){return tabs.filter(t=>selected.has(t.id) && validUrl(t.url))}
function saveDialog(closeAfter,strictProtection=false){
 const list=validTabs();if(!list.length){notify('Hãy chọn ít nhất một trang web http hoặc https.');return}const unsupported=tabs.filter(t=>selected.has(t.id)&&!validUrl(t.url));const choices=groups.some(g=>g.id==='inbox')?groups:[{id:'inbox',name:'Để sau',icon:'✦'},...groups];
 showDialog(`<h2>${closeAfter?'Lưu & đóng tab':'Lưu tab đã chọn'}</h2><p>${closeAfter?'Các tab được chọn sẽ được lưu trước khi đóng. Tab chưa đang xem lúc xem trước sẽ được giữ lại nếu đang xem lúc kiểm tra đóng. Nội dung chưa lưu có thể bị mất.':'Tạo bản sao trong nhóm; tab đang mở không thay đổi.'} Chỉ xử lý các tab được đánh dấu; các tab bỏ chọn sẽ vẫn được chọn trong danh sách.${strictProtection?' Bước chuyển workspace sẽ giữ lại tab đang xem, ghim, phát âm thanh hoặc website được bảo vệ, kể cả khi trạng thái thay đổi.':''}</p><label class="field">Lưu vào nhóm<select name="group">${choices.map(g=>`<option value="${esc(g.id)}">${esc(g.icon)} ${esc(g.name)}</option>`).join('')}</select></label><div class="dialoglist session-picker">${list.map(t=>`<label><input type="checkbox" name="tab" value="${t.id}" checked><span>${esc(t.title||t.url)}<small>${esc(t.url)}${closeAfter&&protectedPreview(t.url)?' · Website được bảo vệ: chỉ lưu bản sao, không đóng':''}</small></span></label>`).join('')}${unsupported.length?`<b>Bỏ qua: ${unsupported.length} tab không hỗ trợ</b>${unsupported.map(t=>`<div>• ${esc(t.title||t.url||'Tab')} · Chỉ hỗ trợ URL http/https.</div>`).join('')}`:''}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="${closeAfter?'danger-soft':'primary'}">${closeAfter?'Lưu & đóng đã chọn':'Lưu bản sao đã chọn'}</button></div>`,async(f,d)=>{
 const ids=new Set(f.getAll('tab').map(Number)),chosen=list.filter(t=>ids.has(t.id));if(!chosen.length)throw Error('Hãy chọn ít nhất một tab.');const latest=await chrome.storage.local.get('groups');const currentGroups=Array.isArray(latest.groups)?latest.groups:[];let target=currentGroups.find(g=>g.id===f.get('group'));if(!target&&f.get('group')==='inbox'){target={id:'inbox',name:'Để sau',icon:'✦',color:'#7771df',createdAt:Date.now(),items:[]};currentGroups.unshift(target)}if(!target)throw Error('Nhóm không còn tồn tại.');let prepared=[],skippedCount=0;
 for(const t of chosen){try{const current=await chrome.tabs.get(t.id);if(current.incognito||current.url!==t.url||current.windowId!==t.windowId||!validUrl(current.url)||(strictProtection&&(PresetTools.reason(current)||await Protection.check(chrome,current.url)))){skippedCount++;continue}prepared.push({tabId:t.id,windowId:t.windowId,wasActive:!!t.active,url:current.url,item:{id:id(),url:current.url,title:current.title||current.url,createdAt:Date.now(),tags:[]}})}catch{skippedCount++}}
 if(!prepared.length)throw Error('Các tab đã thay đổi hoặc không còn mở.');if(closeAfter)await RecoveryPoint.captureIfEnabled(chrome,prepared,Date.now(),id);target.items.unshift(...prepared.map(x=>x.item));try{await chrome.storage.local.set({groups:currentGroups})}catch{throw Error('Không xác nhận được việc lưu; kiểm tra nhóm đích trước khi thử lại. Chưa yêu cầu đóng tab.')}
 for(const entry of prepared)selected.delete(entry.tabId);let result;if(closeAfter){try{result=await BatchTools.closeSaved(chrome,prepared,'Lưu & đóng thủ công',id,async (t,e)=>!t.incognito&&(e.wasActive||!t.active)&&(!strictProtection||!PresetTools.reason(t))&&!await Protection.check(chrome,t.url))}catch(e){d.close();try{await load()}catch(err){console.error(err)}notify('Đã lưu tab nhưng không thể ghi lịch sử; không đóng tab nào.');return}}
 d.close();let refreshFailed=false;try{await load()}catch(e){refreshFailed=true;console.error(e)}const closed=result?.batch.items.filter(x=>x.status==='closed').length||0;const suffix=(skippedCount?` Bỏ qua ${skippedCount} tab đã thay đổi.`:'')+(refreshFailed?' Không thể làm mới; hãy tải lại trang.':'');notify((closeAfter?`Đã lưu ${prepared.length} tab, đóng ${closed}. ${result.stopped?'Lượt dọn bị gián đoạn; xem Lịch sử dọn.':'Xem chi tiết tại Lịch sử dọn.'}`:`Đã lưu ${prepared.length} tab.`)+suffix,closed?result.batch.id:null);
 });
}

function matches(...values){return values.some(v=>String(v||'').toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi')))}
function rowTab(t,extra=''){const native=nativeGroups.find(g=>g.id===t.groupId&&g.windowId===t.windowId);const host=(()=>{try{return new URL(t.url).hostname||t.url}catch{return t.url||'Trang bị hạn chế'}})();return `<div class="row"><input type="checkbox" data-select="${t.id}" aria-label="Chọn ${esc(t.title)}" ${selected.has(t.id)?'checked':''}><div class="favicon">${validUrl(t.url)?`<img src="${esc(FaviconTools.url(t.url,chrome.runtime.getURL('/_favicon/')))}" alt="">`:'◈'}</div><div class="rowtext"><div class="rowtitle">${esc(t.title||t.url||'Tab không có tiêu đề')}</div><div class="rowurl">${esc(host)} · ${esc(t.url||'Không có URL')}${extra?' · '+esc(extra):''}</div></div><div class="badges">${t.groupId>=0?`<span class="badge native-${NativeGroups.colors.includes(native?.color)?native.color:'grey'}">${esc(native?.title||'Nhóm Chrome')}</span>`:''}${t.active?'<span class="badge">Đang xem</span>':''}${t.pinned?'<span class="badge">Đã ghim</span>':''}${t.audible?'<span class="badge">Có âm thanh</span>':''}${t.discarded?'<span class="badge">Đã nghỉ</span>':''}${protectedPreview(t.url)?'<span class="badge">Website được bảo vệ</span>':''}</div><div class="rowactions">${t.groupId>=0?`<button data-action="select-native" data-native="${t.groupId}" data-window="${t.windowId}" aria-label="Chọn mọi tab nhóm ${esc(native?.title||'Chrome không tên')} trong cửa sổ ${t.windowId}, kể cả tab đang ẩn" title="Chọn mọi tab trong nhóm Chrome này, kể cả tab bị lọc ẩn">Chọn nhóm</button><button data-action="edit-native" data-native="${t.groupId}">Sửa nhóm</button>`:''}<button data-action="switch" data-id="${t.id}">Đến tab ↗</button><button data-action="pin" data-id="${t.id}">${t.pinned?'Bỏ ghim':'Ghim'}</button><button data-action="discard" data-id="${t.id}" title="Cho tab nghỉ">Nghỉ</button><button data-action="close" data-id="${t.id}" title="Đóng tab">✕</button></div></div>`}
function pinDialog(chosen,pinned,clearSelection){
 const eligible=chosen.filter(t=>!!t.pinned!==pinned),unchanged=chosen.length-eligible.length;
 if(!eligible.length){notify(pinned?'Các tab đã chọn đều đã ghim.':'Các tab đã chọn đều chưa ghim.');return}
 showDialog(`<h2>${pinned?'Ghim':'Bỏ ghim'} tab?</h2><p>Chỉ các tab được đánh dấu sẽ được xử lý, kể cả tab đã chọn nhưng bị ẩn bởi tìm kiếm. ${pinned?'Chrome có thể chuyển tab được ghim về đầu thanh tab và đưa tab ra khỏi nhóm Chrome.':'Chrome có thể thay đổi vị trí tab trên thanh tab.'} ${unchanged?`${unchanged} tab đã ở trạng thái mong muốn sẽ bỏ qua.`:''}</p><div class="dialoglist session-picker">${eligible.map(t=>`<label><input type="checkbox" name="tab" value="${t.id}" checked><span>${esc(t.title||t.url||'Tab')}<small>${esc(t.url||'')}${pinned&&t.groupId>=0?' · Đang thuộc nhóm Chrome':''}</small></span></label>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">${pinned?'Ghim':'Bỏ ghim'} đã chọn</button></div>`,async(f,d)=>{const ids=new Set(f.getAll('tab').map(Number));const plan=eligible.filter(t=>ids.has(t.id));if(!plan.length)throw Error('Hãy chọn ít nhất một tab.');const results=[];for(const t of plan){const result=await PinTools.set(chrome,t,pinned);results.push({name:t.title||t.url||'Tab',...(result.error?{error:result.error}:{})})}if(clearSelection)selected.clear();d.close();try{await load()}catch(e){console.error(e)}bulkResult(pinned?'Kết quả ghim tab':'Kết quả bỏ ghim tab',results)});
}
function bulkSleepDialog(){
 const chosen=tabs.filter(t=>selected.has(t.id));const reason=t=>protectedPreview(t.url)?'Website được bảo vệ':t.active?'Đang xem':t.pinned?'Đã ghim':t.audible?'Đang phát âm thanh':t.discarded?'Đã nghỉ':t.incognito?'Ẩn danh':'';const eligible=chosen.filter(t=>!reason(t)),protectedTabs=chosen.filter(reason);if(!eligible.length){notify('Không có tab đủ điều kiện cho nghỉ.');return}
 showDialog(`<h2>Cho các tab đã chọn nghỉ?</h2><p>Chỉ các tab được đánh dấu sẽ được xử lý. Trang sẽ tải lại khi mở; biểu mẫu chưa lưu hoặc tác vụ nền có thể mất. Tab đang xem, ghim, phát âm thanh, đã nghỉ và website được bảo vệ được bỏ qua.</p><div class="dialoglist session-picker">${eligible.map(t=>`<label><input type="checkbox" name="tab" value="${t.id}" checked><span>${esc(t.title||t.url||'Tab')}<small>${esc(t.url||'')}</small></span></label>`).join('')}${protectedTabs.length?`<b>Bỏ qua (${protectedTabs.length})</b>${protectedTabs.map(t=>`<div>• ${esc(t.title||t.url||'Tab')} · ${esc(reason(t))}</div>`).join('')}`:''}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Cho nghỉ đã chọn</button></div>`,async(f,d)=>{const ids=new Set(f.getAll('tab').map(Number));const plan=eligible.filter(t=>ids.has(t.id));if(!plan.length)throw Error('Hãy chọn ít nhất một tab.');const results=[];for(const t of plan){const name=t.title||t.url||'Tab';try{if(await Protection.check(chrome,t.url)){results.push({name,error:'Website được bảo vệ; không thực hiện.'});continue}const result=await DiscardTools.request(chrome,t);results.push(result.status==='discarded'?{name}:{name,error:DiscardTools.message(result.status)})}catch(e){results.push({name,error:'Không xác nhận được: '+e.message})}}selected.clear();d.close();await load();bulkResult('Kết quả cho tab nghỉ',results)});
}

function bulkCloseDialog(){
 const chosen=tabs.filter(t=>selected.has(t.id));const reason=t=>t.incognito?'Tab ẩn danh':!validUrl(t.url)?'Chỉ hỗ trợ tab web http/https':protectedPreview(t.url)?'Website hoặc URL được bảo vệ':'';
 const eligible=chosen.filter(t=>!reason(t)),skipped=chosen.filter(reason),risk=t=>[t.active?'Đang xem':'',t.pinned?'Đã ghim':'',t.audible?'Đang phát âm thanh':''].filter(Boolean).join(' · ');
 if(!eligible.length){notify('Không có tab web đủ điều kiện để đóng.');return}
 showDialog(`<h2>Đóng các tab đã chọn?</h2><p>Không tạo bản lưu trong nhóm và không tạo điểm khôi phục trước lượt này. Tabspace ghi URL vào Lịch sử dọn trước khi đóng; chỉ URL được xác nhận đóng có thể mở lại. Nội dung chưa lưu và trạng thái trang có thể mất. Bao gồm cả lựa chọn đang ẩn; chỉ tab đánh dấu trong bản xem trước mới được xử lý. Tab đang xem, ghim hoặc phát âm thanh mặc định không được đánh dấu.</p><div class="dialoglist session-picker">${eligible.map(t=>`<label><input type="checkbox" name="tab" value="${t.id}" ${risk(t)?'':'checked'}><span>${esc(t.title||t.url)}<small>${esc(t.url)}${risk(t)?' · '+esc(risk(t))+' · chỉ đóng nếu bạn đánh dấu':''}</small></span></label>`).join('')}${skipped.length?`<b>Không thể chọn (${skipped.length})</b>${skipped.map(t=>`<div>• ${esc(t.title||t.url||'Tab')} · ${esc(reason(t))}</div>`).join('')}`:''}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="danger-soft">Đóng các tab được đánh dấu</button></div>`,async(f,d)=>{
  const ids=new Set(f.getAll('tab').map(Number)),plan=eligible.filter(t=>ids.has(t.id));if(!plan.length)throw Error('Hãy đánh dấu ít nhất một tab.');
  const entries=plan.map(t=>({tabId:t.id,windowId:t.windowId,url:t.url,wasActive:!!t.active,wasPinned:!!t.pinned,wasAudible:!!t.audible,item:{title:t.title||t.url}}));let result;
  try{result=await BatchTools.closeSaved(chrome,entries,'Đóng nhiều tab (không lưu)',id,async(t,e)=>!t.incognito&&(!t.active||e.wasActive)&&(!t.pinned||e.wasPinned)&&(!t.audible||e.wasAudible)&&!await Protection.check(chrome,t.url))}catch{throw Error('Không ghi được nhật ký; chưa yêu cầu đóng tab. Kiểm tra lịch sử trước khi thử lại.')}
  const results=result.batch.items.map((item,i)=>{if(item.status==='closed'){selected.delete(entries[i].tabId);return {name:item.title}}const explanation=item.status==='skipped'?'Tab đã đổi, được bảo vệ hoặc không còn đủ điều kiện.':item.status==='closing'?'Không xác nhận được việc đóng; kiểm tra Chrome trước khi thử lại.':'Chưa xử lý; kiểm tra lịch sử trước khi thử lại.';return {name:item.title,error:explanation}});
  d.close();let refreshFailed=false;try{await load()}catch(e){refreshFailed=true;console.error(e)}bulkResult('Kết quả đóng tab'+(refreshFailed?' · Không thể làm mới, hãy tải lại trang':''),results,results.some(x=>!x.error)?result.batch.id:null);
 });
}

function nativeGroupDialog(){
 const chosen=tabs.filter(t=>selected.has(t.id)),windows=NativeGroups.selectedWindows(chosen);const usable=windows.filter(w=>w.eligible.length);if(!usable.length){notify('Chọn ít nhất một tab chưa ghim để tạo nhóm Chrome.');return}
 showDialog(`<h2>Tạo nhóm Chrome</h2><p>Đây là nhóm gốc trên thanh tab Chrome, khác nhóm đã lưu trong Tabspace. Mỗi nhóm chỉ thuộc một cửa sổ; tab đang thuộc nhóm khác sẽ được chuyển khỏi nhóm cũ. Tab ghim và các cửa sổ khác sẽ bỏ qua.</p><label class="field">Cửa sổ<select name="window" required>${usable.map(w=>`<option value="${w.windowId}">Cửa sổ ${[...new Set(tabs.map(t=>t.windowId))].indexOf(w.windowId)+1} · ${w.eligible.length} tab đủ điều kiện</option>`).join('')}</select></label><label class="field">Tên nhóm<input name="name" maxlength="100" placeholder="Tên nhóm Chrome (không bắt buộc)"></label><label class="field">Màu Chrome<select name="color">${NativeGroups.colors.map(c=>`<option value="${c}">${esc(nativeColorNames[c])}</option>`).join('')}</select></label><div class="dialoglist">${chosen.map(t=>`<div>• ${esc(t.title||t.url||'Tab')} · Cửa sổ ${[...new Set(tabs.map(x=>x.windowId))].indexOf(t.windowId)+1}${t.pinned?' · Đã ghim, sẽ bỏ qua':''}${t.groupId>=0?' · Đang có nhóm':''}</div>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Tạo nhóm</button></div>`,async(f,d)=>{const windowId=Number(f.get('window'));if(!usable.some(w=>w.windowId===windowId))throw Error('Cửa sổ không hợp lệ.');const result=await NativeGroups.create(chrome,chosen,windowId,String(f.get('name')).trim(),String(f.get('color')));selected.clear();d.close();await load();showDialog(`<h2>Đã tạo nhóm Chrome</h2><p>Đã chuyển ${result.grouped} tab vào nhóm. ${result.updateError?'Nhóm đã được tạo, nhưng Chrome không cập nhật được tên hoặc màu: '+esc(result.updateError):''}</p>${result.skipped.length?`<div class="dialoglist"><b>Tab đã thay đổi hoặc không còn đủ điều kiện:</b>${result.skipped.map(x=>`<div>• ${esc(x)}</div>`).join('')}</div>`:''}<div class="dialogactions"><button value="cancel" class="secondary">Đóng</button></div>`,async(_f,dialog)=>dialog.close())});
}
const nativeColorNames={grey:'Xám',blue:'Xanh dương',red:'Đỏ',yellow:'Vàng',green:'Xanh lá',pink:'Hồng',purple:'Tím',cyan:'Xanh ngọc',orange:'Cam'};
function nativeUngroupDialog(){
 const chosen=tabs.filter(t=>selected.has(t.id)&&t.groupId>=0);if(!chosen.length){notify('Chọn tab đang thuộc nhóm Chrome để bỏ nhóm.');return}
 showDialog(`<h2>Bỏ nhóm Chrome?</h2><p>${chosen.length} tab được chọn sẽ rời nhóm Chrome. Tab không bị đóng và bản lưu Tabspace không thay đổi. Những tab không thuộc nhóm sẽ được bỏ qua.</p><div class="dialoglist">${chosen.map(t=>`<div>• ${esc(t.title||t.url||'Tab')}</div>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Bỏ nhóm</button></div>`,async(_f,d)=>{const result=await NativeGroups.ungroup(chrome,chosen);selected.clear();d.close();await load();showDialog(`<h2>Đã bỏ nhóm</h2><p>Chrome đã nhận yêu cầu bỏ nhóm ${result.ungrouped} tab.</p>${result.skipped.length?`<div class="dialoglist"><b>Bỏ qua vì tab đã thay đổi:</b>${result.skipped.map(x=>`<div>• ${esc(x)}</div>`).join('')}</div>`:''}<div class="dialogactions"><button value="cancel" class="secondary">Đóng</button></div>`,async(_f,dialog)=>dialog.close())});
}
async function nativeEditDialog(groupId){
 let original;try{original=await chrome.tabGroups.get(groupId)}catch{notify('Nhóm Chrome không còn tồn tại hoặc không thể truy cập.');return}
 showDialog(`<h2>Sửa nhóm Chrome</h2><p>Thay đổi tên, màu và trạng thái nhóm trên thanh tab Chrome; nhóm đã lưu trong Tabspace không đổi.</p><label class="field">Tên nhóm<input name="name" maxlength="100" value="${esc(original.title||'')}"></label><label class="field">Màu Chrome<select name="color">${NativeGroups.colors.map(c=>`<option value="${c}" ${c===original.color?'selected':''}>${esc(nativeColorNames[c])}</option>`).join('')}</select></label><label class="checkline"><input type="checkbox" name="collapsed" ${original.collapsed?'checked':''}> Thu gọn nhóm</label><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Lưu thay đổi</button></div>`,async(f,d)=>{const current=await chrome.tabGroups.get(groupId);if(current.windowId!==original.windowId||current.title!==original.title||current.color!==original.color||current.collapsed!==original.collapsed)throw Error('Nhóm Chrome đã thay đổi; hãy mở lại để chỉnh sửa.');const color=String(f.get('color'));if(!NativeGroups.colors.includes(color))throw Error('Màu không hợp lệ.');await chrome.tabGroups.update(groupId,{title:String(f.get('name')).trim(),color,collapsed:f.has('collapsed')});d.close();await load();notify('Đã cập nhật nhóm Chrome.')});
}

function renderOpenFilters(){
 const select=$('#windowFilter'),ids=OpenFilter.windowIds(tabs),options='<option value="">Tất cả cửa sổ</option>'+ids.map((w,i)=>`<option value="${w}">Cửa sổ ${i+1}</option>`).join('')+(openWindowFilter&&!ids.some(w=>String(w)===openWindowFilter)?`<option value="${esc(openWindowFilter)}">Cửa sổ không còn mở</option>`:'');
 if(select.innerHTML!==options)select.innerHTML=options;select.value=openWindowFilter;$('#statusFilter').value=openStatusFilter;const groupSelect=$('#groupFilter'),groups=OpenFilter.groupOptions(tabs,nativeGroups),groupOptions='<option value="all">Tất cả nhóm</option><option value="ungrouped">Không có nhóm</option>'+groups.map(g=>`<option value="${esc(g.key)}">${esc(g.title)} · Cửa sổ ${ids.indexOf(g.windowId)+1}</option>`).join('')+(!['all','ungrouped'].includes(openGroupFilter)&&!groups.some(g=>g.key===openGroupFilter)?`<option value="${esc(openGroupFilter)}">Nhóm không còn tab hiển thị</option>`:'');if(groupSelect.innerHTML!==groupOptions)groupSelect.innerHTML=groupOptions;groupSelect.value=openGroupFilter;$('#sortOpen').value=openSort;
}
function renderOpen(){const windowIds=OpenFilter.windowIds(tabs);const visible=tabs.filter(t=>OpenFilter.matches(t,openWindowFilter,openStatusFilter,openGroupFilter)&&matches(t.title,t.url,nativeGroups.find(g=>g.id===t.groupId&&g.windowId===t.windowId)?.title));const windows=windowIds.filter(w=>visible.some(t=>t.windowId===w));$('#contentArea').innerHTML=windows.length?windows.map(w=>{const ts=OpenFilter.order(visible.filter(t=>t.windowId===w),openSort);return `<div class="sectionhead"><div><h2>Cửa sổ ${windowIds.indexOf(w)+1}</h2><p>Các tab phù hợp trong cửa sổ này</p></div><div class="section-actions"><span class="sectioncount">${ts.length} tab đang thấy</span><button class="textbutton" data-action="select-window" data-window="${w}" aria-label="Chọn mọi tab trong cửa sổ ${windowIds.indexOf(w)+1}, kể cả tab đang ẩn" title="Chọn mọi tab trong cửa sổ, kể cả tab bị lọc ẩn">Chọn cả cửa sổ</button></div></div><div class="card">${ts.map(t=>rowTab(t)).join('')}</div>`}).join(''):'<div class="empty"><b>Không tìm thấy tab nào</b>Thử thay đổi từ khóa hoặc bộ lọc.</div>'}

async function selectOpenScope(windowId,groupId=null){
 if(!Number.isSafeInteger(windowId)||windowId<0||(groupId!==null&&(!Number.isSafeInteger(groupId)||groupId<0)))throw Error('Cửa sổ hoặc nhóm Chrome không hợp lệ.');
 const sourceView=view;await load();if(view!==sourceView)return;const candidates=tabs.filter(t=>t.windowId===windowId&&(groupId===null||t.groupId===groupId));if(!candidates.length){notify(groupId===null?'Cửa sổ không còn tab có thể chọn.':'Nhóm Chrome không còn tab có thể chọn.');return}
 for(const tab of candidates)selected.add(tab.id);selectionAnchor=null;render();const visible=new Set([...document.querySelectorAll('[data-select]')].map(x=>Number(x.dataset.select))),hidden=candidates.filter(t=>!visible.has(t.id)).length;
 const selector=groupId===null?'select-window':'select-native';[...document.querySelectorAll('[data-action]')].find(b=>b.dataset.action===selector&&Number(b.dataset.window)===windowId&&(groupId===null||Number(b.dataset.native)===groupId))?.focus({preventScroll:true});
 notify(`Đã chọn ${candidates.length} tab ${groupId===null?'trong cửa sổ':'trong nhóm Chrome'}.${hidden?` ${hidden} tab đang ẩn bởi tìm kiếm hoặc bộ lọc.`:''} Hãy xem trước trước khi lưu hoặc đóng.`);
}

