 $('#contentArea').innerHTML=info+(visible.length?visible.map(g=>`<div class="sectionhead"><div><h2>${esc(g.tabs[0].title||g.url)}</h2><p>${esc(g.url)}</p></div><span class="sectioncount">${g.tabs.length} tab</span></div><div class="card">${g.tabs.map(t=>rowTab(t,`Cửa sổ ${windowIds.indexOf(t.windowId)+1}`)).join('')}</div>`).join(''):'<div class="empty"><b>Không có tab trùng phù hợp</b>Chỉ các tab http/https có URL giống hệt mới được liệt kê.</div>');
