 const sources=groups.filter(g=>!w.groupIds.includes(g.id)).map(g=>({id:g.id,name:g.name,version:JSON.stringify(g)})),plan=WorkspaceTools.transition(w,groups,tabs,t=>PresetTools.reason(t)||(protectedPreview(t.url)?'Website được bảo vệ':''));
 const openPlan=BulkTools.openPlan(groups,w.groupIds.map(gid=>BulkTools.key('group',gid)));
