chrome.tabs.onRemoved.addListener(()=>load().catch(console.error));chrome.tabs.onUpdated.addListener(()=>load().catch(console.error));chrome.tabs.onCreated.addListener(()=>load().catch(console.error));chrome.storage.onChanged.addListener((changes,area)=>{if(area==='local'&&(changes.groups||changes.smartGroups||changes.workspaces||changes.snapshots||changes.presets||changes.reminderState||changes.remindersPaused||changes.automationPaused||changes.openGraceMinutes||changes.rehearsalConfig||changes.rehearsalRuns||changes.autoCloseConfig||changes.autoCloseRuns||changes.reminderNotifications||changes.reminderBadgeEnabled||changes.quietHours||changes.deferFullscreenNotifications||changes.autoSnapshotConfig||changes.recoverySettings||changes.appearance||changes.protectedDomains||changes.protectedUrls||Object.keys(changes).some(k=>k.startsWith(BatchTools.prefix)||k.startsWith(TrashTools.prefix))))load().catch(console.error)});
function scheduleDayRefresh(){const now=new Date(),next=new Date(now.getFullYear(),now.getMonth(),now.getDate()+1);setTimeout(()=>{render();scheduleDayRefresh()},next.getTime()-now.getTime()+1000)}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)render()});scheduleDayRefresh();
load().then(async()=>{const params=new URLSearchParams(location.search);const saveId=params.get('saveClose'),presetId=params.get('preset'),openInbox=params.get('view')==='inbox',openPresets=params.get('view')==='presets',openAttention=params.get('view')==='attention';if(saveId||presetId||openInbox||openPresets||openAttention){history.replaceState(null,'',dashboardUrl);if(saveId){const tab=tabs.find(t=>t.id===Number(saveId));if(!tab||tab.incognito||!validUrl(tab.url)){notify('Tab không còn tồn tại hoặc không được hỗ trợ.');return}selected.add(tab.id);render();saveDialog(true)}else if(presetId){view='presets';render();await previewPreset(presetId)}else if(openInbox){view='inbox';render()}else if(openPresets){view='presets';render()}else if(openAttention){view='attention';render()}}}).catch(e=>notify('Không tải được dữ liệu: '+e.message));
